    #[test]
    fn snapshot_keeps_sessions_separate_when_only_one_reads_before_writing() {
        let c = conn();
        let session_a = json!({ "agent_id": "session:a" });
        let session_b = json!({ "agent_id": "session:b" });

        record(
            &c,
            1,
            "tool_call",
            "open_session",
            "ok",
            Some(0),
            Some(&session_a),
        )
        .unwrap();
        record(
            &c,
            2,
            "tool_call",
            "recall",
            "ok",
            Some(1),
            Some(&session_a),
        )
        .unwrap();
        record(
            &c,
            3,
            "tool_call",
            "ingest_file",
            "ok",
            Some(1),
            Some(&session_a),
        )
        .unwrap();
        record(
            &c,
            4,
            "tool_call",
            "open_session",
            "ok",
            Some(0),
            Some(&session_b),
        )
        .unwrap();
        record(
            &c,
            5,
            "tool_call",
            "ingest_commit",
            "ok",
            Some(1),
            Some(&session_b),
        )
        .unwrap();
        record(
            &c,
            6,
            "tool_call",
            "working_set",
            "ok",
            Some(1),
            Some(&session_b),
        )
        .unwrap();

        let snapshot = snapshot(&c, 1).unwrap();
        let a = snapshot
            .memory_habits
            .iter()
            .find(|habit| habit.agent_id == "session:a")
            .unwrap();
        let b = snapshot
            .memory_habits
            .iter()
            .find(|habit| habit.agent_id == "session:b")
            .unwrap();

        assert_eq!((a.memory_reads, a.attributed_writes), (1, 1));
        assert_eq!(a.read_before_first_write, Some(true));
        assert_eq!((b.memory_reads, b.attributed_writes), (1, 1));
        assert_eq!(b.read_before_first_write, Some(false));
    }

    #[test]
    fn successful_overlap_preflight_counts_as_memory_read_before_first_write() {
        let c = conn();
        let session = json!({ "agent_id": "session:preflight" });

        record(
            &c,
            1,
            "tool_call",
            "open_session",
            "ok",
            Some(0),
            Some(&session),
        )
        .unwrap();
        record(
            &c,
            2,
            "tool_call",
            "check_overlap",
            "ok",
            Some(1),
            Some(&session),
        )
        .unwrap();
        record(
            &c,
            3,
            "tool_call",
            "ingest_file",
            "ok",
            Some(1),
            Some(&session),
        )
        .unwrap();

        let snapshot = snapshot(&c, 1).unwrap();
        let habit = snapshot
            .memory_habits
            .iter()
            .find(|habit| habit.agent_id == "session:preflight")
            .unwrap();

        // ADR-0066 moved impact retrieval into check_overlap; excluding it made
        // a successful preflight look identical to writing without memory.
        assert_eq!(habit.memory_reads, 1);
        assert_eq!(habit.read_before_first_write, Some(true));
    }

    #[test]
    fn failed_reads_do_not_count_and_no_write_has_no_verdict() {
        let c = conn();
        let failed = json!({ "agent_id": "session:failed" });
        let read_only = json!({ "agent_id": "session:read-only" });

        record(
            &c,
            1,
            "tool_call",
            "open_session",
            "ok",
            Some(0),
            Some(&failed),
        )
        .unwrap();
        record(
            &c,
            2,
            "tool_call",
            "recall",
            "error",
            Some(1),
            Some(&failed),
        )
        .unwrap();
        record(
            &c,
            3,
            "tool_call",
            "ingest_file",
            "ok",
            Some(1),
            Some(&failed),
        )
        .unwrap();
        record(
            &c,
            4,
            "tool_call",
            "open_session",
            "ok",
            Some(0),
            Some(&read_only),
        )
        .unwrap();
        record(
            &c,
            5,
            "tool_call",
            "get_impact_radius",
            "ok",
            Some(1),
            Some(&read_only),
        )
        .unwrap();

        let snapshot = snapshot(&c, 1).unwrap();
        let failed = snapshot
            .memory_habits
            .iter()
            .find(|habit| habit.agent_id == "session:failed")
            .unwrap();
        let read_only = snapshot
            .memory_habits
            .iter()
            .find(|habit| habit.agent_id == "session:read-only")
            .unwrap();

        assert_eq!(failed.memory_reads, 0);
        assert_eq!(failed.read_before_first_write, Some(false));
        assert_eq!(read_only.memory_reads, 1);
        assert_eq!(read_only.attributed_writes, 0);
        assert_eq!(read_only.read_before_first_write, None);
    }

    #[test]
    fn memory_habits_are_bounded_to_the_most_recent_sessions() {
        let c = conn();
        for index in 0..40 {
            record(
                &c,
                index,
                "tool_call",
                "open_session",
                "ok",
                Some(0),
                Some(&json!({ "agent_id": format!("session:{index:02}") })),
            )
            .unwrap();
        }

        let snapshot = snapshot(&c, 1).unwrap();
        assert_eq!(snapshot.memory_habits.len(), MEMORY_HABIT_LIMIT);
        assert_eq!(snapshot.memory_habits[0].agent_id, "session:39");
        assert!(snapshot
            .memory_habits
            .iter()
            .all(|habit| habit.agent_id != "session:00"));
    }
